-- EvidenceLoop database schema.
-- Run this once in the Supabase SQL editor for your project. It is idempotent.
--
-- Access model
--   * The backend writes everything using the secret key, which bypasses RLS.
--   * Signed-in users may only READ rows belonging to work orders they own
--     (needed for Supabase Realtime in the browser). There are no client-side
--     insert/update/delete policies, so the browser cannot alter evidence,
--     decisions, or the audit trail.
--   * Ids and timestamps are generated by the backend.

create table if not exists public.work_orders (
  id uuid primary key,
  owner_id uuid not null references auth.users (id) on delete cascade,
  title text not null,
  description text not null default '',
  location text not null default '',
  template_id text,
  status text not null check (status in
    ('AWAITING_EVIDENCE', 'ANALYZING', 'NEEDS_EVIDENCE', 'CONTRADICTED', 'VERIFIED')),
  simulated boolean not null default false,
  created_at timestamptz not null,
  updated_at timestamptz not null
);

create table if not exists public.requirements (
  id uuid primary key,
  work_order_id uuid not null references public.work_orders (id) on delete cascade,
  position integer not null,
  title text not null,
  description text not null default '',
  mandatory boolean not null default true,
  evidence_needs jsonb not null default '[]'::jsonb,   -- [{ kind, instruction }]
  status text not null check (status in
    ('PROVEN', 'NOT_PROVEN', 'UNCERTAIN', 'CONTRADICTED', 'ANALYZING')),
  current_assessment_id uuid,
  updated_at timestamptz not null
);

create table if not exists public.evidence (
  id uuid primary key,
  work_order_id uuid not null references public.work_orders (id) on delete cascade,
  kind text not null,
  file_name text not null,
  mime_type text not null,
  size_bytes bigint not null,
  sha256 text not null,
  storage_path text not null,
  note text not null default '',
  request_id uuid,
  uploaded_by uuid not null,
  created_at timestamptz not null
);

create table if not exists public.analysis_runs (
  id uuid primary key,
  work_order_id uuid not null references public.work_orders (id) on delete cascade,
  trigger text not null check (trigger in ('manual', 'new_evidence')),
  trigger_evidence_id uuid,
  requirement_ids jsonb not null default '[]'::jsonb,
  provider text not null,
  model text,
  simulated boolean not null default false,
  status text not null check (status in ('RUNNING', 'COMPLETED', 'FAILED')),
  error text,
  started_at timestamptz not null,
  completed_at timestamptz
);

-- Append-only: Requirement → Evidence → Observation → Reasoning → Decision.
create table if not exists public.assessments (
  id uuid primary key,
  work_order_id uuid not null references public.work_orders (id) on delete cascade,
  requirement_id uuid not null references public.requirements (id) on delete cascade,
  run_id uuid not null references public.analysis_runs (id) on delete cascade,
  status text not null check (status in ('PROVEN', 'NOT_PROVEN', 'UNCERTAIN', 'CONTRADICTED')),
  reasoning text not null,
  confidence double precision check (confidence is null or (confidence >= 0 and confidence <= 1)),
  observations jsonb not null default '[]'::jsonb,     -- [{ evidenceId, kind, text, startSec, endSec }]
  missing_evidence jsonb not null default '[]'::jsonb,
  policy_notes jsonb not null default '[]'::jsonb,
  provider text not null,
  model text,
  simulated boolean not null default false,
  created_at timestamptz not null
);

create table if not exists public.evidence_requests (
  id uuid primary key,
  work_order_id uuid not null references public.work_orders (id) on delete cascade,
  run_id uuid not null references public.analysis_runs (id) on delete cascade,
  requirement_ids jsonb not null default '[]'::jsonb,
  kind text not null,
  instruction text not null,
  status text not null check (status in ('OPEN', 'FULFILLED', 'SUPERSEDED')),
  fulfilled_by_evidence_id uuid,
  created_at timestamptz not null,
  updated_at timestamptz not null
);

-- Append-only audit trail.
create table if not exists public.audit_events (
  id uuid primary key,
  work_order_id uuid not null references public.work_orders (id) on delete cascade,
  run_id uuid,
  actor text not null,
  type text not null,
  summary text not null,
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null
);

create index if not exists work_orders_owner_idx on public.work_orders (owner_id, created_at desc);
create index if not exists requirements_work_order_idx on public.requirements (work_order_id, position);
create index if not exists evidence_work_order_idx on public.evidence (work_order_id, created_at);
create index if not exists assessments_work_order_idx on public.assessments (work_order_id);
create index if not exists analysis_runs_work_order_idx on public.analysis_runs (work_order_id, started_at);
create index if not exists evidence_requests_work_order_idx on public.evidence_requests (work_order_id, created_at);
create index if not exists audit_events_work_order_idx on public.audit_events (work_order_id, created_at);

-- ---------- Row Level Security ----------

alter table public.work_orders enable row level security;
alter table public.requirements enable row level security;
alter table public.evidence enable row level security;
alter table public.analysis_runs enable row level security;
alter table public.assessments enable row level security;
alter table public.evidence_requests enable row level security;
alter table public.audit_events enable row level security;

drop policy if exists "Owners can read their work orders" on public.work_orders;
create policy "Owners can read their work orders" on public.work_orders
  for select to authenticated
  using (owner_id = (select auth.uid()));

do $$
declare
  child text;
begin
  foreach child in array array[
    'requirements', 'evidence', 'analysis_runs', 'assessments', 'evidence_requests', 'audit_events'
  ] loop
    execute format('drop policy if exists "Owners can read" on public.%I', child);
    execute format(
      'create policy "Owners can read" on public.%I for select to authenticated using (
         exists (
           select 1 from public.work_orders w
           where w.id = %I.work_order_id and w.owner_id = (select auth.uid())
         )
       )', child, child);
  end loop;
end $$;

-- ---------- Realtime ----------
-- The dashboard subscribes to these tables to update live as the agent works.

do $$
declare
  t text;
begin
  foreach t in array array['work_orders', 'requirements', 'evidence_requests', 'audit_events'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;

-- ---------- Storage ----------
-- Private bucket. No storage policies are defined, so the browser cannot read or
-- write it directly; the backend uploads files and hands out short-lived signed URLs.

insert into storage.buckets (id, name, public)
values ('evidence', 'evidence', false)
on conflict (id) do nothing;
